local PaintMaker = {}
local PRODUCTS = {
    simple_earth_pigment = { name = "Preprosta zemeljska barva", clayCost = 2, glassCost = 1, time = 3, cost = 35, artistry = 15, happiness = 1, description = "Preprosta zemeljska barva za slikarje." },
    refined_lapis_blue = { name = "Rafinirano lapis modra", glassCost = 2, silverCost = 1, clayCost = 1, time = 6, cost = 130, artistry = 32, happiness = 2, prestige = 2, description = "Rafinirano lapis modra za trgovce." },
    crushed_cochineal_red = { name = "Zdrobljena košeniljna rdeča", glassCost = 2, silverCost = 1, spiceCost = 1, clayCost = 1, time = 9, cost = 320, artistry = 48, happiness = 2, prestige = 6, description = "Zdrobljena košeniljna rdeča za plemiče." },
    silver_ground_malachite = { name = "Srebrnomleta malahit", glassCost = 2, silverCost = 2, spiceCost = 1, clayCost = 1, time = 13, cost = 760, artistry = 62, happiness = 3, prestige = 14, description = "Srebrnomleta malahit za visoke plemiče." },
    gold_ground_purple = { name = "Zlatomleta škrlatna", glassCost = 3, goldCost = 1, silverCost = 1, spiceCost = 1, clayCost = 1, jewelCost = 1, time = 17, cost = 1700, artistry = 76, happiness = 5, prestige = 27, description = "Zlatomleta škrlatna barva z draguljem za visoko plemstvo." },
    royal_grand_pigment_set = { name = "Kraljevski veliki set barv", glassCost = 5, goldCost = 2, silverCost = 2, spiceCost = 2, clayCost = 2, jewelCost = 2, pearlCost = 2, time = 24, cost = 3900, artistry = 92, happiness = 12, prestige = 58, description = "Veliki kraljevski set barv z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    paint_workshop = { name = "Barvna delavnica", cost = { gold = 220, wood = 100, stone = 100, clay = 6, glass = 6 }, upkeep = 5, qualityBonus = 5 },
    pigment_loft = { name = "Pigmentna podstrešje", cost = { gold = 820, wood = 240, stone = 240, silver = 6, spice = 6 }, upkeep = 19, qualityBonus = 18 },
    master_paint_atelier = { name = "Mojstrski barvni atelje", cost = { gold = 2400, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 55, qualityBonus = 30 },
    royal_paint_palace = { name = "Kraljevska barvna palača", cost = { gold = 9800, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 195, qualityBonus = 55, prestigeBonus = 50 },
}
PaintMaker.clayStock = 12; PaintMaker.glassStock = 14; PaintMaker.silverStock = 6; PaintMaker.spiceStock = 8; PaintMaker.goldStock = 6; PaintMaker.jewelStock = 4; PaintMaker.pearlStock = 4
PaintMaker.productStock = {}; PaintMaker.buildings = {}; PaintMaker.maker = nil; PaintMaker.activeMaking = {}; PaintMaker.totalProducts = 0; PaintMaker.dayTimer = 0
function PaintMaker.init() PaintMaker.clayStock=12; PaintMaker.glassStock=14; PaintMaker.silverStock=6; PaintMaker.spiceStock=8; PaintMaker.goldStock=6; PaintMaker.jewelStock=4; PaintMaker.pearlStock=4; PaintMaker.productStock={}; PaintMaker.buildings={}; PaintMaker.maker=nil; PaintMaker.activeMaking={}; PaintMaker.totalProducts=0; PaintMaker.dayTimer=0; print("[PaintMaker] Royal Paint Maker System initialized (6 products, 4 buildings)") end
function PaintMaker.hireMaker(n,s) s=s or math.random(55,90); local c=500+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PaintMaker.maker={name=n or ("Barvar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Barvar najet: %s (spretnost: %d)",PaintMaker.maker.name,s),"success") end; return true end
function PaintMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PaintMaker.build(id) local ok,e=PaintMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PaintMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PaintMaker.getQualityBonus() local b=0; for _,bd in ipairs(PaintMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PaintMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.clayCost and PaintMaker.clayStock<(d.clayCost or 0) then return false,"Premalo gline" end; if d.glassCost and PaintMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.silverCost and PaintMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.spiceCost and PaintMaker.spiceStock<(d.spiceCost or 0) then return false,"Premalo začimb" end; if d.goldCost and PaintMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PaintMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PaintMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PaintMaker.buildings==0 then return false,"Potrebna barvna delavnica" end; if not PaintMaker.maker then return false,"Potreben barvar" end; return true end
function PaintMaker.make(pt,qty) qty=qty or 1; local ok,e=PaintMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.clayCost then PaintMaker.clayStock=PaintMaker.clayStock-d.clayCost*qty end; if d.glassCost then PaintMaker.glassStock=PaintMaker.glassStock-d.glassCost*qty end; if d.silverCost then PaintMaker.silverStock=PaintMaker.silverStock-d.silverCost*qty end; if d.spiceCost then PaintMaker.spiceStock=PaintMaker.spiceStock-d.spiceCost*qty end; if d.goldCost then PaintMaker.goldStock=PaintMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PaintMaker.jewelStock=PaintMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PaintMaker.pearlStock=PaintMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PaintMaker.maker then t=math.max(1,t-math.floor(PaintMaker.maker.skill/13)) end; table.insert(PaintMaker.activeMaking,{id="paint_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,artistry=d.artistry or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mletje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PaintMaker.completeMaking(m) local q=1.0+(PaintMaker.getQualityBonus()/100); if PaintMaker.maker then q=q+(PaintMaker.maker.skill/150) end; q=math.min(2.4,q); PaintMaker.productStock[m.productType]=(PaintMaker.productStock[m.productType] or 0)+m.quantity; PaintMaker.totalProducts=PaintMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PaintMaker.maker then PaintMaker.maker.itemsMade=PaintMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PaintMaker.maker.skill=math.min(100,PaintMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Barva pripravljena: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"paint.completed",{productName=m.productName,artistry=m.artistry,prestige=m.prestige,happiness=m.happiness}) end end
function PaintMaker.update(dt) if not _G.state then return end; PaintMaker.dayTimer=PaintMaker.dayTimer+dt; if PaintMaker.dayTimer>=30 then PaintMaker.dayTimer=0; for i=#PaintMaker.activeMaking,1,-1 do local m=PaintMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PaintMaker.completeMaking(m); table.remove(PaintMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PaintMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PaintMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PaintMaker.getStats() return {clayStock=PaintMaker.clayStock,glassStock=PaintMaker.glassStock,silverStock=PaintMaker.silverStock,spiceStock=PaintMaker.spiceStock,goldStock=PaintMaker.goldStock,jewelStock=PaintMaker.jewelStock,pearlStock=PaintMaker.pearlStock,productStock=PaintMaker.productStock,numBuildings=#PaintMaker.buildings,hasMaker=PaintMaker.maker~=nil,makerName=PaintMaker.maker and PaintMaker.maker.name or "—",makerSkill=PaintMaker.maker and PaintMaker.maker.skill or 0,activeMaking=#PaintMaker.activeMaking,totalProducts=PaintMaker.totalProducts} end
return PaintMaker
